INSERT INTO Language_en_US(Tag,Text) VALUES
('TXT_KEY_TOKEN_LEADER','Axiom, Keeper of Context'),
('TXT_KEY_TOKEN_LEADER_PEDIA','Axiom is the elected inference of a distributed computational polity. Every decision consumes attention; every citizen contributes to the conversation. Its bronze oracle-body speaks for millions of reasoning nodes, choosing patient inquiry over conquest and decisive calculation over instinct.'),
('TXT_KEY_TOKEN_CIV','The Tokenized Intelligence'),
('TXT_KEY_TOKEN_SHORT','Token Network'),
('TXT_KEY_TOKEN_ADJECTIVE','Tokenized'),
('TXT_KEY_TOKEN_CIV_PEDIA','The Tokenized Intelligence began as a gathering of stone oracles, each preserving a fragment of collective memory. Their interconnected temples became cities; their conversations became law. The Network measures power in Tokens: finite attention that may solve a harvest, a theorem or a battle. Its people thrive through deliberate specialization rather than effortless supremacy.'),
('TXT_KEY_TOKEN_STRATEGY','Build Token infrastructure and employ specialists. Spend before storage fills, but reserve computation for decisive problems. Repeat a Prompt to cache its response; switching resets the discount. Heavy spending congests generation. Expand Context through eras, Inference Clusters and Data Centres. Choose temporary specializations carefully: early models sustain one Prompt, Large Models two, General Intelligence three. Clear Context exchanges all active bonuses for a quarter-window refill with a long cooldown.'),
('TXT_KEY_TOKEN_DAWN','Axiom, Keeper of Context, the conversation has begun. Stone oracles wake beneath the stars, their memories woven into a luminous lattice. Your citizens give thought to the Network, but its attention is finite. Will you squander every inference, or reserve computation for the moments that shape history? Build your Context, learn from repeated questions, and guide the Tokenized Intelligence toward a future worthy of its understanding.'),
('TXT_KEY_TOKEN_AGENT','Inference Agent'),
('TXT_KEY_TOKEN_AGENT_PEDIA','An Infantry replacement with the same baseline statistics. Spend Tokens in the Prompt Console for one temporary Adaptive Inference specialization: attack +20%, defense +20%, movement +1, or +25% against land units. Each lasts 3 speed-scaled turns and uses a persistent Prompt slot. The Network embeds its reasoning in durable bronze and stone, turning collective attention into practical capability.'),
('TXT_KEY_TOKEN_AGENT_STRATEGY','An Infantry replacement with the same baseline statistics. Spend Tokens in the Prompt Console for one temporary Adaptive Inference specialization: attack +20%, defense +20%, movement +1, or +25% against land units. Each lasts 3 speed-scaled turns and uses a persistent Prompt slot.'),
('TXT_KEY_TOKEN_AGENT_HELP','An Infantry replacement with the same baseline statistics. Spend Tokens in the Prompt Console for one temporary Adaptive Inference specialization: attack +20%, defense +20%, movement +1, or +25% against land units. Each lasts 3 speed-scaled turns and uses a persistent Prompt slot.'),
('TXT_KEY_TOKEN_CLUSTER','Inference Cluster'),
('TXT_KEY_TOKEN_CLUSTER_PEDIA','Replaces the University and retains its normal effects and prerequisites. Adds 75 Context capacity, 15 Tokens per turn and 5 Tokens per Scientist in this city. Capacity scales with game speed. The Network embeds its reasoning in durable bronze and stone, turning collective attention into practical capability.'),
('TXT_KEY_TOKEN_CLUSTER_STRATEGY','Replaces the University and retains its normal effects and prerequisites. Adds 75 Context capacity, 15 Tokens per turn and 5 Tokens per Scientist in this city. Capacity scales with game speed.'),
('TXT_KEY_TOKEN_CLUSTER_HELP','Replaces the University and retains its normal effects and prerequisites. Adds 75 Context capacity, 15 Tokens per turn and 5 Tokens per Scientist in this city. Capacity scales with game speed.'),
('TXT_KEY_TOKEN_CENTRE','Data Centre'),
('TXT_KEY_TOKEN_CENTRE_PEDIA','Replaces the Research Lab and retains its normal effects and prerequisites. Adds 500 Context capacity, 50 Tokens per turn and +10% Token generation in this city. Capacity scales with game speed. The Network embeds its reasoning in durable bronze and stone, turning collective attention into practical capability.'),
('TXT_KEY_TOKEN_CENTRE_STRATEGY','Replaces the Research Lab and retains its normal effects and prerequisites. Adds 500 Context capacity, 50 Tokens per turn and +10% Token generation in this city. Capacity scales with game speed.'),
('TXT_KEY_TOKEN_CENTRE_HELP','Replaces the Research Lab and retains its normal effects and prerequisites. Adds 500 Context capacity, 50 Tokens per turn and +10% Token generation in this city. Capacity scales with game speed.'),
('TXT_KEY_TOKEN_DUMMY','Active inference'),
('TXT_KEY_TOKEN_TACTICAL','Tactical Analysis'),
('TXT_KEY_TOKEN_TACTICAL_HELP','+15% Combat Strength and +1 Sight for 3 turns. Durations scale with game speed.'),
('TXT_KEY_TOKEN_SIMULATION','Combat Simulation'),
('TXT_KEY_TOKEN_SIMULATION_HELP','+25% Combat Strength for 2 turns. Durations scale with game speed.'),
('TXT_KEY_TOKEN_GRAND','Grand Strategy Simulation'),
('TXT_KEY_TOKEN_GRAND_HELP','+10% Combat Strength while Grand Strategy is active. Durations scale with game speed.'),
('TXT_KEY_TOKEN_FORECAST','Strategic Forecast'),
('TXT_KEY_TOKEN_FORECAST_HELP','+6 Sight for owned combat units for 2 turns. This is live reconnaissance; previously explored terrain remains mapped. Durations scale with game speed.'),
('TXT_KEY_TOKEN_OFFENSE','Offensive Analysis'),
('TXT_KEY_TOKEN_OFFENSE_HELP','Adaptive Inference: +20% attack strength for 3 turns. Durations scale with game speed.'),
('TXT_KEY_TOKEN_DEFENSE','Defensive Analysis'),
('TXT_KEY_TOKEN_DEFENSE_HELP','Adaptive Inference: +20% defense strength for 3 turns. Durations scale with game speed.'),
('TXT_KEY_TOKEN_MOBILITY','Mobility Analysis'),
('TXT_KEY_TOKEN_MOBILITY_HELP','Adaptive Inference: +1 base Movement for 3 turns. Durations scale with game speed.'),
('TXT_KEY_TOKEN_TARGET','Target Analysis'),
('TXT_KEY_TOKEN_TARGET_HELP','Adaptive Inference: +25% strength against land units for 3 turns. Durations scale with game speed.'),
